import{_ as a,C as i,o as n,c as r,E as l,a2 as s}from"./chunks/framework.Cm6XCzck.js";const R=JSON.parse('{"title":"Research Runtime Scheduler V1.0","description":"Research Runtime Scheduler 的首个正式发布记录；当前运行基线已经升级到 Scheduler V2.0 与 Runtime Center V4。","frontmatter":{"title":"Research Runtime Scheduler V1.0","description":"Research Runtime Scheduler 的首个正式发布记录；当前运行基线已经升级到 Scheduler V2.0 与 Runtime Center V4。","outline":"deep"},"headers":[],"relativePath":"zh/publications/research-runtime-scheduler-v1.0.md","filePath":"zh/publications/research-runtime-scheduler-v1.0.md","lastUpdated":1785829946000}'),c={name:"zh/publications/research-runtime-scheduler-v1.0.md"};function o(d,e,u,h,p,m){const t=i("ArticleCover");return n(),r("div",null,[l(t,{image:"/assets/covers/research-runtime-scheduler-v1.svg",kicker:"数字员工工场 · Runtime 历史发布",title:"Research Runtime Scheduler V1.0",summary:"Research Operating System 首个正式调度器与运行控制平面发布记录。",version:"V1.0",status:"2026-08-02 发布 · Historical Release",languageHref:"/en/publications/research-runtime-scheduler-v1.0",languageLabel:"English"}),e[0]||(e[0]=s(`<div class="info custom-block"><p class="custom-block-title">当前运行基线</p><p>当前正式运行体系已经升级为：</p><ul><li><strong>Research Runtime Center V4</strong>；</li><li><strong>Research Runtime Scheduler V2.0</strong>；</li><li><strong>研究报告生产机 V1.3</strong>；</li><li><strong>Research Intelligence System V1.0</strong>；</li><li>八个正式 Runtime 任务，新增每日 15:00 Production；</li><li>20:00 Publication 只负责完整候选的 GitHub 与网站发版。</li></ul><p><a href="/joinwell52/zh/runtime/v4">查看当前 V4 运行规范 →</a><br><a href="./research-report-production-engine-v1.3">查看研究报告生产机 V1.3 →</a></p></div><h2 id="v1-0-的历史意义" tabindex="-1">V1.0 的历史意义 <a class="header-anchor" href="#v1-0-的历史意义" aria-label="Permalink to &quot;V1.0 的历史意义&quot;">​</a></h2><p>Research Runtime Scheduler V1.0 首次把 Research Runtime Center 建立为 Research Operating System 的正式运行控制平面。</p><p>它确立了以下原则：</p><ul><li>Research Runtime 而不是单个自动任务，是数字研究员的运行控制平面；</li><li>GitHub Scheduler 只负责打开执行槽，不得制造完成事实；</li><li>正式执行必须写入 Runtime Record；</li><li>只允许 <code>Running</code>、<code>Completed</code>、<code>Blocked</code>、<code>Failed</code>、<code>Skipped</code>、<code>Waiting</code> 六种状态；</li><li>正式发布必须形成 GitHub Commit 与 Commit Verify；</li><li>没有 Runtime Record 的发布不属于正式运行结果。</li></ul><h2 id="v1-0-发布元数据" tabindex="-1">V1.0 发布元数据 <a class="header-anchor" href="#v1-0-发布元数据" aria-label="Permalink to &quot;V1.0 发布元数据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>能力</td><td>Research Runtime Scheduler</td></tr><tr><td>历史版本</td><td>V1.0</td></tr><tr><td>发布日期</td><td>2026-08-02</td></tr><tr><td>时区</td><td><code>Asia/Shanghai</code></td></tr><tr><td>当时数字研究员</td><td>研究报告生产机 V1.0</td></tr><tr><td>当前数字研究员</td><td><a href="./research-report-production-engine-v1.3">研究报告生产机 V1.3</a></td></tr><tr><td>唯一事实源</td><td>GitHub 仓库 <code>joinwell52-AI/joinwell52</code></td></tr><tr><td>Runtime Record</td><td><code>research/runtime/YYYY/MM/YYYY-MM-DD-runtime.md</code></td></tr></tbody></table><h2 id="v1-0-的七个任务" tabindex="-1">V1.0 的七个任务 <a class="header-anchor" href="#v1-0-的七个任务" aria-label="Permalink to &quot;V1.0 的七个任务&quot;">​</a></h2><p>V1.0 以七个正式任务为基线：Engine、Queue、Knowledge、Architecture、Publication、Weekly、Academic。</p><p>该版本尚未包含独立的 15:00 Production，因此写作、配图、证据与出版编辑没有形成单独的下午生产班次。</p><h2 id="从-v1-0-到-v2-0" tabindex="-1">从 V1.0 到 V2.0 <a class="header-anchor" href="#从-v1-0-到-v2-0" aria-label="Permalink to &quot;从 V1.0 到 V2.0&quot;">​</a></h2><p>Scheduler V2.0 增加并明确：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>09:00 Engine</span></span>
<span class="line"><span>10:00 Queue + Research Intelligence + 三栏选题</span></span>
<span class="line"><span>11:00 Knowledge</span></span>
<span class="line"><span>周一 12:00 Architecture</span></span>
<span class="line"><span>15:00 Production → 完整 Publication Candidate</span></span>
<span class="line"><span>20:00 Publication → GitHub + Website + Commit Verify</span></span>
<span class="line"><span>周日 20:30 Weekly</span></span>
<span class="line"><span>周三 10:00 Academic</span></span></code></pre></div><p>同时引入：</p><ul><li>三条情报发现管线；</li><li>三个栏目分别选题；</li><li>每个定时任务的结构化工作成果；</li><li>三栏计划；</li><li>Publication Candidate 批次；</li><li>运营中心自动投影。</li></ul><h2 id="v1-0-runtime-gate" tabindex="-1">V1.0 Runtime Gate <a class="header-anchor" href="#v1-0-runtime-gate" aria-label="Permalink to &quot;V1.0 Runtime Gate&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Research Runtime</span></span>
<span class="line"><span>→ Runtime Record</span></span>
<span class="line"><span>→ GitHub Commit</span></span>
<span class="line"><span>→ Commit Verify</span></span>
<span class="line"><span>→ Official Publication</span></span></code></pre></div><p>V2.0 在此基础上进一步把 Production Candidate 作为 15:00 与 20:00 之间的正式交接对象。</p><h2 id="当前权威实现" tabindex="-1">当前权威实现 <a class="header-anchor" href="#当前权威实现" aria-label="Permalink to &quot;当前权威实现&quot;">​</a></h2><ul><li><a href="./../runtime/v4">Research Runtime Center V4</a></li><li><a href="./../runtime/research-intelligence">Research Intelligence System V1.0</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/runtime/README.md" target="_blank" rel="noreferrer">Runtime Charter</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/runtime/SCHEDULER.json" target="_blank" rel="noreferrer">Scheduler V2.0 Manifest</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/runtime/WORKER-PROMPTS-V2.md" target="_blank" rel="noreferrer">Worker Contracts V2</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/releases/research-runtime-scheduler-v1.0/RELEASE.md" target="_blank" rel="noreferrer">V1.0 Historical Release Record</a></li></ul>`,20))])}const g=a(c,[["render",o]]);export{R as __pageData,g as default};
